(()=>{
 const form=document.querySelector('#subscription-builder');if(!form)return;const R=globalThis.LPGRSubscriptionRules;
 const summary=document.querySelector('#subscription-summary'),schedule=document.querySelector('#subscription-schedule'),parcels=document.querySelector('#subscription-parcels'),status=document.querySelector('#subscription-availability'),result=document.querySelector('#subscription-result'),submit=document.querySelector('#subscription-submit');
 let catalog=[],config={},ready=false,enabled=false,busy=false,current=null,startedAt=Date.now();const units=new Map();
 const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(n);
 const reservations=()=>[...form.querySelectorAll('[name="reserve-title"]:checked')].map(x=>Number(x.value));
 function lines(){const output=[];for(const box of form.querySelectorAll('[name="subscription-title"]:checked')){const b=catalog.find(b=>b.number===Number(box.value)),quantity=Number(form.querySelector(`[data-quantity="${b.number}"]`).value);if(!Number.isInteger(quantity)||quantity<1||quantity>(config.max_books||12))throw Error('Vérifiez les quantités.');for(let i=0;i<quantity;i++){const key=b.number+'-'+i;if(!units.has(key))units.set(key,{number:b.number,quantity:1,month:b.available?R.currentMonth():b.release_month,parcel:1});output.push({...units.get(key),key,title:b.title,minimum:b.available?R.currentMonth():b.release_month});}}return output;}
 function autoAssign(){try{const selected=lines(),groups=new Map();for(const line of selected){const count=groups.get(line.month)||0;groups.set(line.month,count+1);line.parcel=0;}let id=0;for(const month of [...groups.keys()].sort()){let count=0;for(const line of selected.filter(x=>x.month===month)){if(count%3===0)id++;units.get(line.key).parcel=id;count++;}}}catch(error){result.textContent=error.message;}}
 function update(rebuild=true){
  current=null;summary.textContent='';parcels.replaceChildren();if(!ready)return;
  let selected=[];try{selected=lines();}catch(error){summary.textContent=error.message;submit.disabled=true;return;}
  if(rebuild){schedule.replaceChildren();for(const line of selected){const row=document.createElement('div');row.className='schedule-row';const name=document.createElement('strong');name.textContent=line.title+' — exemplaire '+(Number(line.key.split('-')[1])+1);const month=document.createElement('input');month.type='month';month.value=line.month;month.min=line.minimum>R.currentMonth()?line.minimum:R.currentMonth();month.setAttribute('aria-label','Mois pour '+name.textContent);const parcel=document.createElement('input');parcel.type='number';parcel.min='1';parcel.max='120';parcel.value=line.parcel;parcel.setAttribute('aria-label','Colis pour '+name.textContent);for(const event of ['input','change']){month.addEventListener(event,()=>{units.get(line.key).month=month.value;update(false);});parcel.addEventListener(event,()=>{units.get(line.key).parcel=Number(parcel.value);update(false);});}row.append(name,document.createTextNode('Mois '),month,document.createTextNode('Colis '),parcel);schedule.append(row);}}
  const reserved=reservations();const billing=form.elements.billing_address;billing.required=selected.length>0;billing.disabled=!selected.length;billing.closest('label').hidden=!selected.length;document.querySelector('#recipient-fields').hidden=!selected.length;document.querySelector('#recipient-fields').disabled=!selected.length;
  try{current=R.quote(catalog,lines(),reserved,config);}catch(error){summary.textContent=error.message;submit.disabled=true;return;}
  summary.textContent=`${current.paid.length} exemplaires · Livres : ${money(current.books)} · Port : ${money(current.shipping)} · Total estimatif : ${money(current.total)}`;
  for(const p of current.parcels){const card=document.createElement('article');card.className='parcel-card';const h=document.createElement('h3');h.textContent=`Colis ${p.id} — ${p.month}`;const list=document.createElement('ul');for(const b of p.books){const li=document.createElement('li');li.textContent=b.title+' — '+money(b.price);list.append(li);}const port=document.createElement('p');port.textContent='Port : '+money(p.shipping);card.append(h,list,port);parcels.append(card);}
  document.querySelector('#reservation-summary').textContent=current.reserved.length?'Réservations sans paiement : '+current.reserved.map(x=>x.title).join(', '):'';submit.disabled=!enabled||busy;
 }
 function request(){if(!current)throw Error('Corrigez la sélection et les colis.');if(!form.reportValidity())return null;const values=Object.fromEntries(new FormData(form));return {...values,terms:values.terms==='on',acknowledge:values.acknowledge==='on',newsletter:values.newsletter==='on',lines:lines().map(({number,quantity,month,parcel})=>({number,quantity,month,parcel})),reservedIds:reservations(),expectedTotal:current.total,startedAt};}
 function message(data){return R.summary(current)+`\n\nAcheteur : ${data.nom}\nE-mail : ${data.email}\nFacturation : ${data.billing_address||''}\nDestinataire : ${data.recipient_name||''}\n${data.address||''}\n${data.postal_code||''} ${data.city||''}\nMot pour la carte : ${data.card_message||''}\nCGV acceptées et demande sans paiement comprise. Infolettre : ${data.newsletter?'oui':'non'}`;}
 form.addEventListener('input',e=>{if(e.target.hasAttribute('data-quantity')){autoAssign();update();}});
 form.addEventListener('change',e=>{if(['subscription-title','reserve-title'].includes(e.target.name)||e.target.dataset.quantity){autoAssign();update();}});document.querySelector('#auto-parcels').addEventListener('click',()=>{autoAssign();update();});
 form.addEventListener('submit',async e=>{e.preventDefault();if(!enabled||busy)return;let data;try{data=request();}catch(error){result.textContent=error.message;return;}if(!data)return;busy=true;submit.disabled=true;result.textContent='Envoi…';try{const r=await fetch('/api/subscription',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(35000)});const answer=await r.json();if(!r.ok||answer.ok!==true)throw Error(answer.error||'Envoi non confirmé.');result.textContent=answer.message+(answer.newsletterStatus==='confirmation_sent'?' Confirmez séparément votre inscription à l’infolettre dans le message reçu.':answer.newsletterStatus==='unavailable'?' L’inscription à l’infolettre n’a pas pu être envoyée ; votre demande d’abonnement est bien transmise.':'');startedAt=Date.now();}catch(error){result.textContent=error.message+' Votre saisie est conservée.';}finally{busy=false;update(false);result.focus();}});
 document.querySelector('#subscription-email').addEventListener('click',()=>{try{const data=request();if(data)location.href='mailto:contact@lesplusgrandsracontes.fr?subject='+encodeURIComponent('Demande d’abonnement — facture et virement')+'&body='+encodeURIComponent(message(data));}catch(error){result.textContent=error.message;}});
 document.querySelector('#subscription-download').addEventListener('click',()=>{try{const data=request();if(!data)return;const url=URL.createObjectURL(new Blob([message(data)],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='demande-abonnement.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){result.textContent=error.message;}});
 Promise.all([fetch('/content.json',{cache:'no-store'}).then(r=>r.json()),fetch('/api/subscription',{cache:'no-store'}).then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([data,service])=>{catalog=data.books;config=data.subscription||{};ready=true;enabled=service.enabled===true;const selected=Number(new URLSearchParams(location.search).get('reserver'));for(const box of form.querySelectorAll('input[type=checkbox][value]'))if(Number(box.value)===selected)box.checked=true;status.textContent=enabled?'Votre demande sera transmise aux auteurs.':'Envoi direct indisponible : préparez un e-mail ou téléchargez votre récapitulatif.';autoAssign();update();}).catch(()=>status.textContent='Catalogue indisponible ; contactez contact@lesplusgrandsracontes.fr.');
})();
